using System.Collections.Generic;
using System.Linq;
using TourCore.Application.Common.Exceptions;
namespace TourCore.Application.Tours { public class TourServiceCommandValidator { public void Validate(CreateTourServiceCommand c){var e=new List<string>();if(c==null)e.Add("Request body is required.");else{if(c.ServiceTypeId<=0)e.Add("ServiceTypeId must be greater than zero.");if(string.IsNullOrWhiteSpace(c.Name))e.Add("Name is required.");else if(c.Name.Trim().Length>256)e.Add("Name must be 256 characters or less.");if(c.ParentServiceId.HasValue&&c.ParentServiceId<=0)e.Add("ParentServiceId must be greater than zero.");if(c.IsHidden&&c.IsRemovable)e.Add("A hidden service cannot be removable.");if(c.IsHidden&&c.IsOptional)e.Add("A hidden service cannot be optional.");}if(e.Count>0)throw new ValidationException(e);} public void Validate(ReorderTourServicesCommand c){if(c==null||c.ServiceIds==null)throw new ValidationException(new[]{"ServiceIds is required."});if(c.ServiceIds.Any(x=>x<=0)||c.ServiceIds.Count!=c.ServiceIds.Distinct().Count())throw new ValidationException(new[]{"ServiceIds must contain unique positive identifiers."});} } }
